    pub const TERMINAL_COUNT: usize = 7;
    pub const INTERNAL_NODE_COUNT: usize = 7;
    pub const NODE_COUNT: usize = 14;
    pub const INTERNAL_NODE_NAMES: [&str; 7] = ["di", "si", "gi", "gm", "sb", "db", "N"];

    pub const BRANCH_COUNT: usize = 19;
